(* [comment removed for export] *)
Lemma NEGI (t v : Z) (fx1 fx2 : FPState) R1 R2 RC Dc M1 model1 LK1 Aw1 s1 sm1 e1 cr1 (M2v : mem) :
  AT t R1 RC Dc M1 model1 LK1 Aw1 s1 sm1 e1 cr1 -> 2 ^ 64 - 32 <= v < 2 ^ 64 ->
  msteps RSEGS (st fx1 R1 0xd081c (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 0xb1b44 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall i, 0 <= i < 2 ^ 64 -> M2v (Z_to_bv 64 i) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 i)) ->
  (forall x, In x PQARI1.RL -> getr R2 (reg x) = getr R1 (reg x)) ->
  getr R2 (reg 1) = Z_to_bv 64 0xd0964 -> getr R2 (reg 10) = Z_to_bv 64 (fb + 992) -> getr R2 (reg 11) = Z_to_bv 64 v ->
  getr R2 (reg 12) = Z_to_bv 64 0 -> getr R2 (reg 14) = Z_to_bv 64 (fb + 1232) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0xd081c M1 model1) K.
Proof using All.
