(* [comment removed for export] *)
Definition XS (c x len : Z) (R3 : bvmap 5 word) (RC : list Z) (Dc : list (list Z)) (M3 : mem) (model3 : Model) (LK3 : list fframe) (Aw3 : list (Z * Z))
           (s3 : PQMA.mpst) (sm3 : PM.strm) (e3 : bool) (cr3 : credit) : Prop :=
  MM RC Dc M3 model3 LK3 Aw3 s3 sa sm3 e3 cr3 eb /\ REGS R3 /\ getr R3 (reg 24) = Z_to_bv 64 (fb + 592 + 24)
  /\ PQMA.cpl s3 (NEMA.ae_a sa) /\ PQRA.minv_d 0 s3 /\ PQMA.p_stk s3 = PQMA.p_stk s /\ PQRA.room_keep s s3 sm sm3
  /\ PM.unread (PQMA.p_src s3) sm3 + c <= PM.unread (PQMA.p_src s) sm /\ 0 <= PM.unread (PQMA.p_src s3) sm3
  /\ RIC cr3 (PNRNA.pot_runA L ar s3 sa) (tsp Dc RC0)
  /\ L5.u64_at RSEGS M3 (V2 - 152) len /\ L5.u64_at RSEGS M3 (V2 - 144) ((fb + 592 + 8) / 8 + 2147450880) /\ L5.u64_at RSEGS M3 (V2 - 136) (fb + 592 + 8)
  /\ L5.u8_at RSEGS M3 (F / 8 + 2147450928) 1 /\ L5.u8_at RSEGS M3 (F + 384) x /\ 0 <= x < 256 /\ 0 <= len < 2 ^ 64.

(* [comment removed for export] *)
Lemma XS_keep (Mx My : mem) (x len lo hi : Z) :
  (forall a, V2 - 152 <= a < V2 - 128 -> My (Z_to_bv 64 a) = Mx (Z_to_bv 64 a)) ->
  (forall a, F / 8 + 2147450928 <= a < F / 8 + 2147450928 + 1 -> My (Z_to_bv 64 a) = Mx (Z_to_bv 64 a)) ->
  (forall a, F + 32 <= a < F + 1024 - 8 -> ~ (F + lo <= a < F + hi) -> My (Z_to_bv 64 a) = Mx (Z_to_bv 64 a)) -> (385 <= lo \/ hi <= 384) ->
  7036928 <= F -> F + 1024 <= 2 ^ 47 ->
  L5.u64_at RSEGS Mx (V2 - 152) len -> L5.u64_at RSEGS Mx (V2 - 144) ((fb + 592 + 8) / 8 + 2147450880) -> L5.u64_at RSEGS Mx (V2 - 136) (fb + 592 + 8) ->
  L5.u8_at RSEGS Mx (F / 8 + 2147450928) 1 -> L5.u8_at RSEGS Mx (F + 384) x ->
  L5.u64_at RSEGS My (V2 - 152) len /\ L5.u64_at RSEGS My (V2 - 144) ((fb + 592 + 8) / 8 + 2147450880) /\ L5.u64_at RSEGS My (V2 - 136) (fb + 592 + 8)
  /\ L5.u8_at RSEGS My (F / 8 + 2147450928) 1 /\ L5.u8_at RSEGS My (F + 384) x.
