Theorem read_item_okF (tspV : Z -> list (list Z) -> list Z -> credit) :
  (forall D, PQRAa.src_read_spec L ar (HIk D) /\ PQRAa.make_ec_spec L ar (HIk D) /\ PNRNA.begin_array_spec RSEGS AD AQ AAD AE L ar (HIk D) /\ PNRNA.begin_object_spec RSEGS AD AQ AAD AE L ar (HIk D)
             /\ PNVA.v_uint64_spec RSEGS AD AQ AAD AE L ar (HIk D) /\ PNVA.v_int64_spec RSEGS AD AQ AAD AE L ar (HIk D) /\ PNVA.v_double_spec RSEGS AD AQ AAD AE L ar (HIk D) /\ PNVA.v_null_spec RSEGS AD AQ AAD AE L ar (HIk D)
             /\ PNVA.v_bool_spec RSEGS AD AQ AAD AE L ar (HIk D) /\ PNRNA.get_size_spec RSEGS AD AQ AAD AE L ar (HIk D) /\ PQRAa.read_span_v_spec L ar (HIk D)
             /\ PNVA.v_bstr_tag_spec RSEGS AD AQ AAD AE L ar (HIk D) /\ PNVA.v_bstr_raw_spec RSEGS AD AQ AAD AE L ar (HIk D) /\ PECVSA.validate_fun_spec RSEGS AD L ar (HIk D) (pa_validate AD)) ->
  PNVA.v_string_specF RSEGS AD AQ AAD AE L ar HIk tspV ->
  (forall t D RC RCv, PMSP.credit_le (tspV t D RCv) (tsp D RC)
                      /\ (forall D', incl D D' -> PMSP.credit_le (PM.credit_add (tsp D' RC) (tspV t D RCv)) (PM.credit_add (tsp D RC) (tspV t D' RCv)))) ->
  PQARITS.TS8A L ar C IL LR HIk tsp TSRESA -> PQARITS.TS12A L ar C IL LR HIk tsp TSRESA ->
  PQRAR.read_item_specFR L ar HIk tsp.
