Lemma potp_nonneg XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 :
  MX XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  0 <= fst (PMSPA.scA L (PQMA.pot_mparser (PMSPA.HV L ar) s1)) /\ 0 <= snd (PMSPA.scA L (PQMA.pot_mparser (PMSPA.HV L ar) s1))
  /\ 0 <= fst (NEMA.pot_aeA L ar sa1) /\ 0 <= snd (NEMA.pot_aeA L ar sa1).
Proof using All.
