(* [comment removed for export] *)
Definition fobjX_spec {XT : Type} (HI : asan_iface) (pc h : Z) (PRE : XT -> bvmap 5 word -> mem -> list fframe -> Z -> Prop) (POST : XT -> bvmap 5 word -> mem -> Z -> Prop) : Prop :=
  forall (x : XT) (fx : FPState) (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K0' : TSet) (LB : list (Z * Z)) (FF0 LK0 : list fframe) (Aw0 : list (Z * Z)) (cr0 : credit) (sp0 r0 o : Z),
    ri_inv HI LB FF0 LK0 cr0 Aw0 M0 (vml_of model0) -> L5CA.amodel_ok Aw0 model0 -> K0' [] ->
    PMSPA.entryA AD L ar R0 M0 sp0 r0 h -> PGSA.ffroomB PQRA.FCM h FF0 LK0 -> PMSPA.ffrsA FF0 sp0 -> sp0 mod 16 = 0 ->
    getr R0 (reg 10) = Z_to_bv 64 o -> PMSPA.aobjA FF0 o 32 -> o mod 8 = 0 -> PMSPA.accA M0 o 32 -> PRE x R0 M0 FF0 o -> PMSTA.base_okA RSEGS AD M0 ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe),
        regs_preserved R0 R' -> POST x R' M' o -> L5CA.ahpres L ar LB FF0 sp0 (PMSPA.pm_scr h) [(o, 32)] M0 M' ->
        model_rt model0 model' -> incl LK' LK0 -> L5CA.amodel_ok Aw0 model' -> ri_inv HI LB FF0 LK' cr0 Aw0 M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r0 M' model') K0') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R0 pc M0 model0) K0'.

Lemma ri_call_fobjX {XT : Type} (PRE : XT -> bvmap 5 word -> mem -> list fframe -> Z -> Prop) (POST : XT -> bvmap 5 word -> mem -> Z -> Prop) (x : XT) XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 : FPState) R1 (pc h ra off : Z) :
  fobjX_spec (HIk Dc) pc h PRE POST -> 1 <= h <= 6 ->
  MX XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 (F + off) -> 32 <= off -> off + 32 <= B - 8 -> off mod 8 = 0 ->
  L5KA.zeros_at M1 (F / 8 + off / 8 + 2147450880) 4 -> PRE x R1 M1 FF' (F + off) ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3,
      regs_preserved R1 R2 -> POST x R2 M3 (F + off) ->
      MX XB RC Dc M3 model3 LK3 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
      (forall a, spc <= a < 2 ^ 47 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F + 32 <= a < F + B - 8 -> ~ (F + off <= a < F + off + 32) -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc M1 model1) K.
Proof using All.
  intros SPX Hh LM X1 RAok X2 X3 X4 X10 Ho1 Ho2 Ho3 ZSH PRE1 KR.
  kitx PQARIKX.ctx_facts CTXF. destruct CTXF as ((FB1 & FB2 & Fal & FBS) & (SLO & SHI & SPT & A16) & (rs & Hfb) & (TOP & _)).
  destruct ENT as (Rra & RAok0 & Rsp & Rgp & Rtp & ASTK & STKSH). rewrite PQAKRF.scr8 in STKSH.
  pose proof LM as (INC & BI & RP1 & EC1 & STEP1 & EE1 & RCH1).
  pose proof G as G'. destruct G' as [Hk GSPT GSLO GSHI GSPC GOCR GOWN GFS1 GFS2 GFCEIL GLKI2 GFLP GFLNC GHH2 GFLC GFR GF8 GFBIG GF32 GFLA GFLR GFLBIG GNCF GNCS].
  pose proof BI as (HH1 & AM1 & MRT1 & INCA1 & INCL1 & ASTK1 & EK1 & DK1 & OWN1 & DSH1).
  pose proof GFR as (GF1 & GF2 & GF3 & GF4). destruct HSPC as (HSP1 & HSP2 & HSP3). kitx PQARIKX.HSPC16 H16. destruct H16 as (HSQ1 & _ & _).
  assert (FOK' : PQRA.frame_okM FF' fb). { split; [exists rs; right; exact Hfb| exact Fal]. }
  assert (FBF : fb + 32 + 2008 <= F \/ F + B <= fb + 32).
  { destruct (APART (fb + 32) 2008 0 0) as (Y & _); [| lia| exact Y].
    intros i Hi. unfold aclient, aclient_g. do 3 right; left. exists (fb, 5, rs). split; [exact Hfb|]. cbn [ff_addr ff_class fst snd]. change (ff_bytes 5) with 2048. lia. }
  pose proof RP1 as (_ & _ & _ & _ & _ & _ & _ & BASE1 & ERR1 & ECs1 & _).
  kitx PQARIKX.wapp_run WAPPR.
  pose proof (HAJ.aior_wf _ _ _ _ _ (HIokF Dc) _ _ _ _ _ _ _ HH1) as (WB1 & _ & FSAPP & _ & _ & _ & _ & _ & _ & _ & _ & NDF1 & _).
  assert (DF1 : 0 <= F / 8) by (apply Z.div_pos; lia).
  assert (DF2 : F / 8 + B / 8 <= 17592186044416).
  { destruct GF8 as (E1 & _ & E3). assert (F / 8 * 8 + B / 8 * 8 <= 2 ^ 47) by lia. lia. }
  assert (DIV8 : (F + off) / 8 = F / 8 + off / 8).
  { destruct GF8 as (E1 & _). replace (F + off) with (F / 8 * 8 + off) by lia. rewrite Z.div_add_l by lia. reflexivity. }
  assert (OM8 : (F + off) mod 8 = 0).
  { destruct GF8 as (E1 & _). replace (F + off) with (off + F / 8 * 8) by lia. rewrite Z_mod_plus_full. exact Ho3. }
  assert (ACC1 : PMSPA.accA M1 (F + off) 32).
  { unfold PMSPA.accA. apply (L5CBR.aacc_of_zero M1 (F + off) 4 (F + off) 32); [| exact OM8| lia| lia| lia].
    unfold shadow_zero, byte_at. intros j Hj. unfold S. rewrite DIV8. apply ZSH. exact Hj. }
  unfold fobjX_spec in SPX.
  apply (SPX x fx1 R1 M1 model1 K ((XB ++ mown s1 sa1) ++ LBX) FF' LK1 Aw1 cr1 spc ra (F + off) HH1 AM1 K0).
  { unfold PMSPA.entryA. rewrite L5K.rl1, L5K.rl2, L5K.rl3, L5K.rl4. split; [exact X1|]. split; [exact RAok|]. split; [exact X2|]. split; [exact X3|]. split; [exact X4|].
    split; [replace spc with (sp - (sp - spc)) by lia; apply (L5SAR.astk_sub ar M1 M1 sp SCR (sp - spc) (PMSPA.pm_scr h) ASTK1 (mem_grows_refl M1)); [lia| unfold PMSPA.pm_scr; lia| unfold PMSPA.pm_scr; lia| replace (sp - (sp - spc)) with spc by lia; exact HSQ1]|].
    rewrite (PQAKRF.scr8 h).
    apply (PMKA.shadow_zero_sub M1 (sp - SCR) (1536 + 256 * 10)); [| | unfold PMSPA.pm_scr; lia| unfold PMSPA.pm_scr; lia| lia|].
    - apply PMKA.mod16_8'. apply (PQARIK.mod_sub sp SCR 16); [lia| exact A16| reflexivity].
    - apply PMKA.mod16_8'. apply (PQARIK.mod_sub spc (PMSPA.pm_scr h) 16); [lia| exact HSQ1| unfold PMSPA.pm_scr; replace (12288 + 2048 * h) with ((768 + 128 * h) * 16) by lia; apply Z_mod_mult].
    - apply (PMKA.stksh_keepA L ar LBX FF sp SCR WR M M1 EK1 WAPPR (sp - SCR) (1536 + 256 * 10)); [unfold PMSPA.pm_scr in *; lia| unfold PMSPA.pm_scr in *; lia| unfold PMSPA.pm_scr in *; lia| | lia| exact STKSH].
