  { apply (PMAUAR.ffroomB_push PQRA.FCM 10 h FF LK LK1 _ FRM INCL1); [exact NDF1| lia]. }
  { apply (PMAUAR.ffrsA_push FF sp spc F 4 (spc + 32) FRS); lia. }
  { exact HSQ1. }
  { exact X10. }
  { exists (F, 4, spc + 32). split; [left; reflexivity|]. cbn [ff_addr ff_class fst snd]. lia. }
  { exact OM8. }
  { exact ACC1. } { exact PRE1. } { exact BASE1. }
  intros fx4 R4 M4 model4 LK4 RP4 POST4 HP4 MRT4 INCL4 AM4 HH4.
  set (Wc := [(F + off, 32)]) in HP4.
  assert (WcR : forall rr a, In rr Wc -> L5.in_rng rr a -> F + off <= a < F + off + 32).
  { intros rr a [<-|[]] Hr. unfold L5.in_rng in Hr. cbn [fst snd] in Hr. exact Hr. }
  assert (WAV : forall rr a, In rr Wc -> L5.in_rng rr a -> ~ (spc <= a < sp) /\ ~ (F / 8 + SB <= a < F / 8 + SB + B / 8)).
