  assert (BI4 : PQAKUF.binv L ar HIk Dc M model LBX FF LK Aw sp SCR spc OWN F 4 WR ((XB ++ mown s1 sa1)) M4 model4 LK4 cr1 Aw1).
  { kitx PQARIKX.binv_calleeX BCX. apply (BCX Dc Dc WR ((XB ++ mown s1 sa1)) ((XB ++ mown s1 sa1)) ((XB ++ mown s1 sa1)) M1 model1 LK1 cr1 Aw1 M4 model4 LK4 cr1 Aw1 spc (PMSPA.pm_scr h) Wc BI HP4 HH4 AM4 MRT4 (incl_refl _) INCL4);
      [unfold PMSPA.pm_scr; lia| unfold PMSPA.pm_scr; lia| lia| intros rr a Hin Hr; destruct (WAV rr a Hin Hr) as (Y1 & Y2); split; [intros Oc; apply Y1; pose proof (GOCR a Oc); lia| exact Y2]| exact WOUT| intros a X0; exact X0]. }
  assert (WAPPc : PMKA.wapp Wc).
  { intros rr [<-|[]]. unfold BIGSHADOW_LO, BIGSHADOW_HI. cbn [fst snd]. destruct GFBIG as [Y|Y]; clear - Y GF1 GF2 GF3 Ho1 Ho2; lia. }
  pose proof (PMASK.frb_of L ar C (HIk Dc) (HIokF Dc) _ _ _ _ _ _ _ HH1) as FRB1. pose proof (PMASK.brb_of L ar C (HIk Dc) (HIokF Dc) _ _ _ _ _ _ _ HH1) as BRB1.
  assert (OUTF : forall i, fb + 32 <= i < fb + 2040 -> ~ (fb + 1232 <= i < fb + 1248) -> L5.outside Wc i).
