Definition ffobj_spec {XT : Type} (pc h gra : Z) (PRE : XT -> bvmap 5 word -> mem -> list fframe -> Z -> Prop)
    (POST : XT -> bvmap 5 word -> mem -> Z -> Z -> Z -> Z -> Prop) : Prop :=
  forall (x : XT) (fx : FPState) (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K0' : TSet) (LB : list (Z * Z)) (FF0 LK0 : list fframe) (Aw0 : list (Z * Z)) (cr0 : credit)
         (sp0 r0 o : Z) (D : list (list Z)),
    ri_inv (HIk D) LB FF0 LK0 cr0 Aw0 M0 (vml_of model0) -> L5CA.amodel_ok Aw0 model0 -> K0' [] ->
    PMSPA.entryA AD L ar R0 M0 sp0 r0 h -> PGSA.ffroomB PQRA.FCM h FF0 LK0 -> PMSPA.ffrsA FF0 sp0 -> sp0 mod 16 = 0 ->
    getr R0 (reg 10) = Z_to_bv 64 o -> PMSPA.aobjA FF0 o 32 -> o mod 8 = 0 -> PMSPA.accA M0 o 32 -> PRE x R0 M0 FF0 o -> PMSTA.base_okA RSEGS AD M0 ->
    PQATSG.gpre L LR gra D 64 cr0 ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (cr' : credit) (p lo hi : Z) (gk : list Z),
        regs_preserved R0 R' -> In gk (PQATSG.GKEYS LR gra) -> POST x R' M' o p lo hi ->
        L5CA.afresh L ar LB (FF0 ++ LK') M' p 64 ->
        L5CA.ahpres L ar LB FF0 sp0 (PMSPA.pm_scr h) [(o, 32)] M0 M' ->
        PMSP.credit_keep cr0 cr' (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
        model_rt model0 model' -> incl LK' LK0 -> incl Aw0 Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv (HIk (gk :: D)) ((p, 64) :: LB) FF0 LK' cr' Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r0 M' model') K0') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R0 pc M0 model0) K0'.

Lemma ri_call_famobj {XT : Type} (PRE : XT -> bvmap 5 word -> mem -> list fframe -> Z -> Prop) (POST : XT -> bvmap 5 word -> mem -> Z -> Z -> Z -> Z -> Prop) (x : XT) XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 : FPState) R1 (pc h gra ra off : Z) :
  ffobj_spec pc h gra PRE POST -> 1 <= h <= 6 ->
  MX XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
