    rewrite (PQAKRF.scr8 h).
    apply (PMKA.shadow_zero_sub M1 (sp - SCR) (1536 + 256 * 10)); [| | unfold PMSPA.pm_scr; lia| unfold PMSPA.pm_scr; lia| lia|].
    - apply PMKA.mod16_8'. apply (PQARIK.mod_sub sp SCR 16); [lia| exact A16| reflexivity].
    - apply PMKA.mod16_8'. apply (PQARIK.mod_sub spc (PMSPA.pm_scr h) 16); [lia| exact HSQ1| unfold PMSPA.pm_scr; replace (12288 + 2048 * h) with ((768 + 128 * h) * 16) by lia; apply Z_mod_mult].
    - apply (PMKA.stksh_keepA L ar LBX FF sp SCR WR M M1 EK1 WAPPR (sp - SCR) (1536 + 256 * 10)); [unfold PMSPA.pm_scr in *; lia| unfold PMSPA.pm_scr in *; lia| unfold PMSPA.pm_scr in *; lia| | lia| exact STKSH].
