  { intros rr a Hin Hr. pose proof (WcR rr a Hin Hr) as X0. unfold SB. split; [unfold PMSPA.pm_scr in GSLO; clear - X0 GFCEIL GSLO HSP1 Ho1 Ho2; lia| destruct GFBIG as [Y|Y]; clear - X0 Y DF1 DF2 Ho1 Ho2 GF1; lia]. }
  assert (WLO : forall rr a, In rr Wc -> L5.in_rng rr a -> a < ahl_ceil ar).
