(* [comment removed for export] *)
Lemma ri_call_ws2d (tswe : list (list Z) -> Z -> list Z -> credit) XB RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 : FPState) R1 (pc h ra off bfb p bv0 bv1 : Z) :
  PQATSW2.ws2d_specF RSEGS AD L ar HIk (fun D _ r RC => tswe D r RC) pc h -> 1 <= h <= 6 ->
  MX ((p, 64) :: XB) RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) -> getr R1 (reg 8) = Z_to_bv 64 sp ->
  getr R1 (reg 10) = Z_to_bv 64 (F + off) -> 32 <= off -> off + 32 <= B - 8 -> off mod 8 = 0 ->
  L5KA.zeros_at M1 (F / 8 + off / 8 + 2147450880) 4 ->
  PQATSG.ws_this_atA RSEGS M1 (F + off) (PQATSG.WDyn bfb p bv0 bv1) ->
  getr R1 (reg 11) = Z_to_bv 64 (fb + 592 + 328) -> PM.vs_size (PQMA.p_tb s1) = 0 ->
  PMSP.credit_le (PM.credit_add (PM.credit_add (PNRNA.pot_runA L ar s1 sa1) (PMSPA.scA L PNRNA.TSRES_ME)) (tswe Dc ra RC)) cr1 ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 (x' : PM.vstr) cr3 (D' : list (list Z)),
      regs_preserved R1 R2 ->
      PM.vstr_at RSEGS PMSPA.accA M3 (fb + 592 + 328) x' -> 1 <= PM.vs_size x' <= 30 -> PQATSS.ts_text RSEGS M3 (fb + 592 + 328) x' -> PQATSW2.ws2_postL (PQMA.p_tb s1) x' ->
      MX ((p, 64) :: XB) RC D' M3 model3 LK3 Aw3 (PQAKWT.with_tb s1 x') sa1 sm1 e1 cr3 b1 ->
      PMSP.credit_keep cr1 cr3 (PM.credit_add (PMSPA.scA L (PQMA.pot_mparser (PMSPA.HV L ar) s1)) (tswe Dc ra RC))
                              (PM.credit_add (PMSPA.scA L (PQMA.pot_mparser (PMSPA.HV L ar) (PQAKWT.with_tb s1 x'))) (tswe D' ra RC)) ->
      incl Dc D' -> incl Aw1 Aw3 ->
      (forall a, spc <= a < 2 ^ 47 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F + 32 <= a < F + B - 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc M1 model1) K.
Proof using All.
