  MX ((p, 64) :: XB) RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> 4096 <= ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) -> getr R1 (reg 8) = Z_to_bv 64 sp ->
  getr R1 (reg 10) = Z_to_bv 64 p ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 Aw3 (Kt : list Z),
      regs_preserved R1 R2 -> (Kt = [HAR.hlr_pc_free LR] \/ Kt = HAR.akey (HAR.hlr_pc_free LR) (ra :: RC)) ->
      MX XB RC (Kt :: Dc) M3 model3 LK1 Aw3 s1 sa1 sm1 e1 (if HAR.warm_ok Kt Dc 64 then (fst cr1 + 1, snd cr1) else cr1) b1 ->
      incl Aw1 Aw3 ->
      (forall a, spc <= a < 2 ^ 47 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F + 32 <= a < F + B - 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 PnLayoutA.ADDR_A.(pa_opdel) M1 model1) K.
Proof using All.
